const width = 900;
const height = 760;

const svg = d3.select('#bubble-chart')
  .attr('viewBox', `0 0 ${width} ${height}`);

const tooltip = d3.select('#tooltip');

function formatMarketCap(value) {
  if (!value || Number.isNaN(value)) return 'N/A';
  const abs = Math.abs(value);
  if (abs >= 1e12) return (value / 1e12).toFixed(2) + 'T';
  if (abs >= 1e9) return (value / 1e9).toFixed(2) + 'B';
  if (abs >= 1e6) return (value / 1e6).toFixed(2) + 'M';
  return d3.format(',')(value);
}

function selectTicker(ticker) {
  d3.selectAll('.bubble').classed('selected', d => d.ticker === ticker);
  d3.selectAll('tbody tr').classed('selected', d => d.ticker === ticker);

  const row = d3.select(`tr[data-ticker="${ticker}"]`).node();
  if (row) {
    row.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }
}

d3.csv('data/stock-descriptions.csv').then(raw => {
  const data = raw
    .sort((a, b) => d3.ascending(a.sector, b.sector) || d3.ascending(a.ticker, b.ticker))
    .map(d => ({
      ticker: d.ticker,
      sector: d.sector,
      name: d['full name'],
      marketCap: d.marketCap ? +d.marketCap : null,
      country: d.country,
      website: d.website,
      isETF: !d.marketCap
    }));

  const sectors = Array.from(new Set(data.map(d => d.sector))).sort();

  const color = d3.scaleOrdinal()
    .domain(sectors)
    .range([
      '#2563eb','#16a34a','#dc2626','#9333ea','#ea580c',
      '#0891b2','#ca8a04','#4f46e5','#db2777','#059669'
    ]);

  const sectorCenters = {};
  const centerRadius = 180;

  sectors.forEach((sector, i) => {
    const angle = (i / sectors.length) * Math.PI * 2;
    sectorCenters[sector] = {
      x: width / 2 + Math.cos(angle) * centerRadius,
      y: height / 2 + Math.sin(angle) * centerRadius * 0.7
    };
  });

  const maxCap = d3.max(data.filter(d => d.marketCap), d => d.marketCap);

  const radiusScale = d3.scaleSqrt()
    .domain([0, maxCap])
    .range([12, 52]);

  data.forEach(d => {
    d.radius = d.marketCap ? radiusScale(d.marketCap) : 14;
  });

  const simulation = d3.forceSimulation(data)
    .force('x', d3.forceX(d => sectorCenters[d.sector].x).strength(0.22))
    .force('y', d3.forceY(d => sectorCenters[d.sector].y).strength(0.22))
    .force('center', d3.forceCenter(width / 2, height / 2))
    .force('charge', d3.forceManyBody().strength(2))
    .force('collide', d3.forceCollide().radius(d => d.radius + 2).iterations(2))
    .stop();

  for (let i = 0; i < 300; i += 1) {
    simulation.tick();
  }

  const nodes = svg.append('g')
    .selectAll('g')
    .data(data)
    .join('g')
    .attr('transform', d => `translate(${d.x},${d.y})`);

  nodes.append('circle')
    .attr('class', 'bubble')
    .attr('r', d => d.radius)
    .attr('fill', d => color(d.sector))
    .on('mouseover', function(event, d) {
      if (d.isETF) return;
      tooltip
        .classed('visible', true)
        .html(`<strong>${d.ticker}</strong><br>${d.name}<br>${d.sector}`)
        .style('left', `${event.pageX + 12}px`)
        .style('top', `${event.pageY - 28}px`);
    })
    .on('mousemove', function(event, d) {
      if (d.isETF) return;
      tooltip
        .style('left', `${event.pageX + 12}px`)
        .style('top', `${event.pageY - 28}px`);
    })
    .on('mouseout', function() {
      tooltip.classed('visible', false);
    })
    .on('click', function(event, d) {
      selectTicker(d.ticker);
    });

  nodes.append('text')
    .attr('class', 'bubble-label')
    .attr('dy', '0.35em')
    .text(d => d.ticker)
    .style('font-size', d => `${Math.max(8, Math.min(12, d.radius / 2.5))}px`)
    .attr('pointer-events', 'none');

  const legend = svg.append('g')
    .attr('class', 'legend')
    .attr('transform', 'translate(20,20)');

  const legendItem = legend.selectAll('g')
    .data(sectors)
    .join('g')
    .attr('transform', (d, i) => `translate(0, ${i * 22})`);

  legendItem.append('rect')
    .attr('width', 14)
    .attr('height', 14)
    .attr('rx', 3)
    .attr('fill', d => color(d));

  legendItem.append('text')
    .attr('x', 22)
    .attr('y', 11)
    .text(d => d);

  const tbody = d3.select('#stock-table tbody');

  tbody.selectAll('tr')
    .data(data)
    .join('tr')
    .attr('data-ticker', d => d.ticker)
    .on('click', function(event, d) {
      selectTicker(d.ticker);
    })
    .html(d => `
      <td>${d.ticker}</td>
      <td>${d.name}</td>
      <td>${d.sector}</td>
      <td>${formatMarketCap(d.marketCap)}</td>
    `);
});
